  ('quant', 'LCM & HCF', 2, 'Three bells ring at intervals of 10, 24 and 30 minutes. They ring together at 9:00 AM. When will they next ring together?', array['10:04 AM', '1:00 PM', '11:00 AM', '10:00 AM'], 2, 'They ring together every LCM(10, 24, 30) = 120 minutes. 9:00 AM + 120 minutes = 11:00 AM.', 40, 'bells_lcm', null, null, null),
  ('quant', 'LCM & HCF', 2, 'Three bells ring at intervals of 12, 15 and 16 minutes. They ring together at 10:00 AM. When will they next ring together?', array['12:00 PM', '2:00 PM', '10:43 AM', '6:00 PM'], 1, 'They ring together every LCM(12, 15, 16) = 240 minutes. 10:00 AM + 240 minutes = 2:00 PM.', 40, 'bells_lcm', null, null, null),
