  ('quant', 'LCM & HCF', 2, 'Three bells ring at intervals of 6, 20 and 24 minutes. They ring together at 7:00 AM. When will they next ring together?', array['9:00 AM', '7:50 AM', '11:00 AM', '8:00 AM'], 0, 'They ring together every LCM(6, 20, 24) = 120 minutes. 7:00 AM + 120 minutes = 9:00 AM.', 40, 'bells_lcm', null, null, null),
  ('quant', 'LCM & HCF', 2, 'Three bells ring at intervals of 5, 6 and 9 minutes. They ring together at 8:00 AM. When will they next ring together?', array['11:00 AM', '9:30 AM', '8:45 AM', '8:20 AM'], 1, 'They ring together every LCM(5, 6, 9) = 90 minutes. 8:00 AM + 90 minutes = 9:30 AM.', 40, 'bells_lcm', null, null, null),
  ('quant', 'LCM & HCF', 2, 'Three bells ring at intervals of 5, 12 and 36 minutes. They ring together at 7:00 AM. When will they next ring together?', array['8:30 AM', '10:00 AM', '7:53 AM', '1:00 PM'], 1, 'They ring together every LCM(5, 12, 36) = 180 minutes. 7:00 AM + 180 minutes = 10:00 AM.', 40, 'bells_lcm', null, null, null),
  ('quant', 'Probability', 2, 'Two fair dice are thrown. What is the probability that the numbers add up to 8?', array['1/6', '5/36', '1/9', '1/8'], 1, 'There are 36 equally likely outcomes. A sum of 8 comes from 5: (2,6), (3,5), (4,4), (5,3), (6,2). So the probability is 5/36.', 40, 'dice_sum', null, null, null),
  ('quant', 'Probability', 2, 'Two fair dice are thrown. What is the probability that the numbers add up to 3?', array['1/12', '1/3', '1/18', '1/36'], 2, 'There are 36 equally likely outcomes. A sum of 3 comes from 2: (1,2), (2,1). So the probability is 2/36 = 1/18.', 40, 'dice_sum', null, null, null),
  ('quant', 'Probability', 2, 'Two fair dice are thrown. What is the probability that the numbers add up to 9?', array['5/36', '1/9', '1/6', '1/12'], 1, 'There are 36 equally likely outcomes. A sum of 9 comes from 4: (3,6), (4,5), (5,4), (6,3). So the probability is 4/36 = 1/9.', 40, 'dice_sum', null, null, null),
  ('quant', 'Probability', 2, 'Two fair dice are thrown. What is the probability that the numbers add up to 6?', array['1/9', '7/36', '1/6', '5/36'], 3, 'There are 36 equally likely outcomes. A sum of 6 comes from 5: (1,5), (2,4), (3,3), (4,2), (5,1). So the probability is 5/36.', 40, 'dice_sum', null, null, null),
  ('quant', 'Probability', 2, 'Two fair dice are thrown. What is the probability that the numbers add up to 10?', array['1/9', '1/18', '1/12', '1/10'], 2, 'There are 36 equally likely outcomes. A sum of 10 comes from 3: (4,6), (5,5), (6,4). So the probability is 3/36 = 1/12.', 40, 'dice_sum', null, null, null),
  ('quant', 'Probability', 2, 'Two fair dice are thrown. What is the probability that the numbers add up to 4?', array['1/4', '1/9', '1/18', '1/12'], 3, 'There are 36 equally likely outcomes. A sum of 4 comes from 3: (1,3), (2,2), (3,1). So the probability is 3/36 = 1/12.', 40, 'dice_sum', null, null, null),
  ('quant', 'Probability', 2, 'Two fair dice are thrown. What is the probability that the numbers add up to 11?', array['1/11', '1/36', '1/12', '1/18'], 3, 'There are 36 equally likely outcomes. A sum of 11 comes from 2: (5,6), (6,5). So the probability is 2/36 = 1/18.', 40, 'dice_sum', null, null, null),
  ('quant', 'Probability', 2, 'Two fair dice are thrown. What is the probability that the numbers add up to 7?', array['7/36', '1/7', '5/36', '1/6'], 3, 'There are 36 equally likely outcomes. A sum of 7 comes from 6: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1). So the probability is 6/36 = 1/6.', 40, 'dice_sum', null, null, null),
  ('quant', 'Probability', 2, 'Two fair dice are thrown. What is the probability that the numbers add up to 5?', array['1/5', '1/9', '1/12', '5/36'], 1, 'There are 36 equally likely outcomes. A sum of 5 comes from 4: (1,4), (2,3), (3,2), (4,1). So the probability is 4/36 = 1/9.', 40, 'dice_sum', null, null, null),
  ('quant', 'Boats & Streams', 2, 'A boat goes 76 km downstream in 4 hours and 17 km upstream in 1 hour. What is the speed of the boat in still water?', array['17 km/h', '19 km/h', '18 km/h', '1 km/h'], 2, 'Downstream speed = 76 ÷ 4 = 19 km/h. Upstream speed = 17 ÷ 1 = 17 km/h. Boat speed = (19 + 17) ÷ 2 = 18 km/h; stream speed = (19 − 17) ÷ 2 = 1 km/h.', 40, 'boat_stream', null, null, null),
  ('quant', 'Boats & Streams', 2, 'A boat goes 22 km downstream in 1 hour and 32 km upstream in 2 hours. What is the speed of the boat in still water?', array['19 km/h', '16 km/h', '22 km/h', '3 km/h'], 0, 'Downstream speed = 22 ÷ 1 = 22 km/h. Upstream speed = 32 ÷ 2 = 16 km/h. Boat speed = (22 + 16) ÷ 2 = 19 km/h; stream speed = (22 − 16) ÷ 2 = 3 km/h.', 40, 'boat_stream', null, null, null),
  ('quant', 'Boats & Streams', 2, 'A boat goes 72 km downstream in 4 hours and 56 km upstream in 4 hours. What is the speed of the boat in still water?', array['16 km/h', '2 km/h', '14 km/h', '18 km/h'], 0, 'Downstream speed = 72 ÷ 4 = 18 km/h. Upstream speed = 56 ÷ 4 = 14 km/h. Boat speed = (18 + 14) ÷ 2 = 16 km/h; stream speed = (18 − 14) ÷ 2 = 2 km/h.', 40, 'boat_stream', null, null, null),
  ('quant', 'Boats & Streams', 2, 'A boat goes 27 km downstream in 3 hours and 20 km upstream in 4 hours. What is the speed of the boat in still water?', array['7 km/h', '5 km/h', '2 km/h', '9 km/h'], 0, 'Downstream speed = 27 ÷ 3 = 9 km/h. Upstream speed = 20 ÷ 4 = 5 km/h. Boat speed = (9 + 5) ÷ 2 = 7 km/h; stream speed = (9 − 5) ÷ 2 = 2 km/h.', 40, 'boat_stream', null, null, null),
  ('quant', 'Boats & Streams', 2, 'A boat goes 36 km downstream in 2 hours and 48 km upstream in 4 hours. What is the speed of the boat in still water?', array['3 km/h', '12 km/h', '15 km/h', '18 km/h'], 2, 'Downstream speed = 36 ÷ 2 = 18 km/h. Upstream speed = 48 ÷ 4 = 12 km/h. Boat speed = (18 + 12) ÷ 2 = 15 km/h; stream speed = (18 − 12) ÷ 2 = 3 km/h.', 40, 'boat_stream', null, null, null),
  ('quant', 'Boats & Streams', 2, 'A boat goes 22 km downstream in 1 hour and 54 km upstream in 3 hours. What is the speed of the stream?', array['20 km/h', '18 km/h', '2 km/h', '22 km/h'], 2, 'Downstream speed = 22 ÷ 1 = 22 km/h. Upstream speed = 54 ÷ 3 = 18 km/h. Boat speed = (22 + 18) ÷ 2 = 20 km/h; stream speed = (22 − 18) ÷ 2 = 2 km/h.', 40, 'boat_stream', null, null, null),
  ('quant', 'Boats & Streams', 2, 'A boat goes 22 km downstream in 2 hours and 5 km upstream in 1 hour. What is the speed of the boat in still water?', array['11 km/h', '8 km/h', '3 km/h', '5 km/h'], 1, 'Downstream speed = 22 ÷ 2 = 11 km/h. Upstream speed = 5 ÷ 1 = 5 km/h. Boat speed = (11 + 5) ÷ 2 = 8 km/h; stream speed = (11 − 5) ÷ 2 = 3 km/h.', 40, 'boat_stream', null, null, null),
  ('quant', 'Boats & Streams', 2, 'A boat goes 76 km downstream in 4 hours and 22 km upstream in 2 hours. What is the speed of the boat in still water?', array['4 km/h', '11 km/h', '15 km/h', '19 km/h'], 2, 'Downstream speed = 76 ÷ 4 = 19 km/h. Upstream speed = 22 ÷ 2 = 11 km/h. Boat speed = (19 + 11) ÷ 2 = 15 km/h; stream speed = (19 − 11) ÷ 2 = 4 km/h.', 40, 'boat_stream', null, null, null),
  ('quant', 'Boats & Streams', 2, 'A boat goes 56 km downstream in 4 hours and 12 km upstream in 2 hours. What is the speed of the stream?', array['10 km/h', '4 km/h', '14 km/h', '6 km/h'], 1, 'Downstream speed = 56 ÷ 4 = 14 km/h. Upstream speed = 12 ÷ 2 = 6 km/h. Boat speed = (14 + 6) ÷ 2 = 10 km/h; stream speed = (14 − 6) ÷ 2 = 4 km/h.', 40, 'boat_stream', null, null, null),
  ('quant', 'Boats & Streams', 2, 'A boat goes 51 km downstream in 3 hours and 28 km upstream in 4 hours. What is the speed of the boat in still water?', array['7 km/h', '5 km/h', '17 km/h', '12 km/h'], 3, 'Downstream speed = 51 ÷ 3 = 17 km/h. Upstream speed = 28 ÷ 4 = 7 km/h. Boat speed = (17 + 7) ÷ 2 = 12 km/h; stream speed = (17 − 7) ÷ 2 = 5 km/h.', 40, 'boat_stream', null, null, null),
  ('quant', 'Boats & Streams', 2, 'A boat goes 66 km downstream in 3 hours and 72 km upstream in 4 hours. What is the speed of the boat in still water?', array['22 km/h', '20 km/h', '18 km/h', '2 km/h'], 1, 'Downstream speed = 66 ÷ 3 = 22 km/h. Upstream speed = 72 ÷ 4 = 18 km/h. Boat speed = (22 + 18) ÷ 2 = 20 km/h; stream speed = (22 − 18) ÷ 2 = 2 km/h.', 40, 'boat_stream', null, null, null),
  ('quant', 'Boats & Streams', 2, 'A boat goes 42 km downstream in 2 hours and 76 km upstream in 4 hours. What is the speed of the stream?', array['21 km/h', '20 km/h', '1 km/h', '19 km/h'], 2, 'Downstream speed = 42 ÷ 2 = 21 km/h. Upstream speed = 76 ÷ 4 = 19 km/h. Boat speed = (21 + 19) ÷ 2 = 20 km/h; stream speed = (21 − 19) ÷ 2 = 1 km/h.', 40, 'boat_stream', null, null, null),
  ('quant', 'Partnership', 2, 'A starts a business with ₹33,000. After 6 months, B joins with ₹55,000. At the end of the year the profit is ₹1,52,900. What is A''s share?', array['₹76,450', '₹1,25,100', '₹69,500', '₹83,400'], 3, 'Compare capital × months: A = ₹33,000 × 12, B = ₹55,000 × 6, a ratio of 6:5. A''s share = 6/11 × ₹1,52,900 = ₹83,400.', 40, 'partnership', null, null, null),
