  ('reasoning', 'Analogies', 1, 'Seed : Tree :: Egg : ?', array['Yolk', 'Nest', 'Shell', 'Bird'], 3, 'A seed grows into a tree; an egg grows into a bird.', 30, 'curated_analogies', null, null, null),
  ('reasoning', 'Analogies', 2, 'Kilometre : Distance :: Kilogram : ?', array['Speed', 'Volume', 'Length', 'Mass'], 3, 'A kilometre is a unit of distance; a kilogram is a unit of mass.', 40, 'curated_analogies', null, null, null),
  ('reasoning', 'Seating Arrangement', 2, 'Five friends sit in a row facing north. C is at the extreme left and E at the extreme right. D sits between C and B, and A is to the immediate right of B. Who sits in the middle?', array['D', 'B', 'A', 'C'], 1, 'From the left: C, D, B, A, E. B is in the middle.', 40, 'curated_seating_arrangement', null, null, null),
  ('reasoning', 'Seating Arrangement', 3, 'Six people P, Q, R, S, T and U sit around a round table facing the centre. P is opposite S. Q is to the immediate left of P and T to the immediate right of P. R is opposite Q. Who is opposite T?', array['Q', 'U', 'R', 'S'], 1, 'Facing the centre, your left is the clockwise side. Going clockwise from P: P, Q, U, S, R, T. T is opposite U.', 55, 'curated_seating_arrangement', null, null, null),
  ('reasoning', 'Seating Arrangement', 2, 'Five houses stand in a row. The white house is at the far left and the yellow house at the far right. The red house is to the right of the green house but to the left of the blue house. Which house is in the middle?', array['Red', 'White', 'Green', 'Blue'], 0, 'From the left: white, green, red, blue, yellow. Red is in the middle.', 40, 'curated_seating_arrangement', null, null, null),
  ('reasoning', 'Seating Arrangement', 2, 'A, B, C, D and E stand in a queue. B is ahead of A but behind E. C is ahead of D but behind A. Who is third in the queue?', array['E', 'C', 'A', 'B'], 2, 'From the front: E, B, A, C, D. A is third.', 40, 'curated_seating_arrangement', null, null, null),
  ('reasoning', 'Ranking', 2, 'Among P, Q, R, S and T, Q is taller than only T. R is taller than Q but shorter than both P and S. P is not the tallest. Who is the tallest?', array['R', 'S', 'Q', 'P'], 1, 'T is shortest, then Q, then R. P and S are taller than R, and P is not the tallest, so S is.', 40, 'curated_ranking', null, null, null),
  ('reasoning', 'Ranking', 1, 'Seven books are stacked in a pile. The Maths book is 4th from the top, and the English book is just above it. How many books are below the English book?', array['5', '4', '2', '3'], 1, 'The English book is 3rd from the top, so 7 − 3 = 4 books are below it.', 30, 'curated_ranking', null, null, null),
  ('reasoning', 'Inequalities', 2, 'If P > Q, Q ≥ R and R > S, which of these is definitely true?', array['Q < S', 'P > S', 'R ≥ P', 'S > Q'], 1, 'P > Q ≥ R > S, so P is greater than S.', 40, 'curated_inequalities', null, null, null),
  ('reasoning', 'Inequalities', 2, 'If A ≥ B, B = C and C > D, which of these is definitely true?', array['A > D', 'D ≥ A', 'B < D', 'A = D'], 0, 'A ≥ B = C > D. Even if A equals B, it is still greater than D.', 40, 'curated_inequalities', null, null, null),
  ('reasoning', 'Inequalities', 2, 'If M < N, N ≤ O and O < P, which of these is definitely true?', array['P ≤ N', 'M ≥ O', 'M < P', 'N > P'], 2, 'M < N ≤ O < P, so M is less than P.', 40, 'curated_inequalities', null, null, null),
  ('reasoning', 'Inequalities', 3, 'If X ≥ Y and Y ≥ Z, which of these must be true?', array['X > Z', 'Z > X', 'Y > X', 'X ≥ Z'], 3, 'X ≥ Y ≥ Z gives X ≥ Z. "X > Z" is not certain, because all three could be equal.', 55, 'curated_inequalities', null, null, null),
