  ('verbal', 'Antonyms', 1, 'Choose the word opposite in meaning to REJECT.', array['Refuse', 'Accept', 'Decline', 'Deny'], 1, 'Reject means to refuse; accept means to take or agree to.', 25, 'curated_antonyms', null, null, null),
  ('verbal', 'Grammar', 1, 'Fill in the blank: She has been working here ___ 2019.', array['from', 'since', 'for', 'by'], 1, 'Use "since" with a starting point in time (2019); "for" goes with a length of time.', 25, 'curated_grammar', null, null, null),
  ('verbal', 'Grammar', 2, 'Fill in the blank: Neither the manager nor the employees ___ present at the meeting.', array['is', 'was', 'were', 'has been'], 2, 'With "neither … nor", the verb agrees with the nearer subject, "employees", which is plural.', 25, 'curated_grammar', null, null, null),
  ('verbal', 'Grammar', 1, 'Fill in the blank: He is good ___ solving puzzles.', array['at', 'with', 'on', 'in'], 0, 'The fixed phrase is "good at" something.', 25, 'curated_grammar', null, null, null),
  ('verbal', 'Grammar', 1, 'Fill in the blank: I prefer tea ___ coffee.', array['from', 'over', 'to', 'than'], 2, 'The verb "prefer" takes "to": prefer A to B.', 25, 'curated_grammar', null, null, null),
  ('verbal', 'Grammar', 2, 'Fill in the blank: Each of the students ___ given a laptop.', array['was', 'have been', 'are', 'were'], 0, '"Each" is singular, so it takes the singular verb "was".', 25, 'curated_grammar', null, null, null),
  ('verbal', 'Grammar', 2, 'Fill in the blank: If I ___ you, I would accept the offer.', array['was', 'be', 'am', 'were'], 3, 'Imaginary conditions use "were" for every subject: "If I were you".', 25, 'curated_grammar', null, null, null),
  ('verbal', 'Grammar', 2, 'Fill in the blank: The train had already left when we ___ the station.', array['had reach', 'reach', 'have reached', 'reached'], 3, 'The later past action takes the simple past: "had left … when we reached".', 25, 'curated_grammar', null, null, null),
  ('verbal', 'Grammar', 1, 'Fill in the blank: She is the ___ of the two sisters.', array['more tall', 'tallest', 'taller', 'most tall'], 2, 'Comparing two people uses the comparative form, "taller".', 25, 'curated_grammar', null, null, null),
  ('verbal', 'Grammar', 1, 'Fill in the blank: Please refrain ___ using your phone during the test.', array['of', 'with', 'to', 'from'], 3, 'The fixed phrase is "refrain from" doing something.', 25, 'curated_grammar', null, null, null),
  ('verbal', 'Grammar', 1, 'Fill in the blank: The committee ___ its decision yesterday.', array['announces', 'announced', 'announcing', 'has announced'], 1, '"Yesterday" is a finished past time, so use the simple past.', 25, 'curated_grammar', null, null, null),
  ('verbal', 'Grammar', 1, 'Fill in the blank: He insisted ___ paying the bill.', array['for', 'on', 'at', 'to'], 1, 'The fixed phrase is "insist on" doing something.', 25, 'curated_grammar', null, null, null),
  ('verbal', 'Grammar', 2, 'Fill in the blank: Hardly had I reached the station ___ the train left.', array['than', 'then', 'and', 'when'], 3, '"Hardly … when" is the fixed pair; "than" goes with "no sooner".', 25, 'curated_grammar', null, null, null),
  ('verbal', 'Idioms', 1, 'What does the idiom "break the ice" mean?', array['Cause a fight', 'Leave suddenly', 'Start a conversation in an awkward situation', 'Make a mistake'], 2, 'To break the ice is to ease tension by starting to talk.', 25, 'curated_idioms', null, null, null),
  ('verbal', 'Idioms', 2, 'What does the idiom "hit the nail on the head" mean?', array['Describe a problem exactly right', 'Hurt someone by accident', 'Fix something badly', 'Work very hard'], 0, 'It means to say exactly what is true or what is causing a problem.', 25, 'curated_idioms', null, null, null),
  ('verbal', 'Idioms', 1, 'What does the idiom "once in a blue moon" mean?', array['Every night', 'At midnight', 'Very soon', 'Very rarely'], 3, 'It describes something that happens very rarely.', 25, 'curated_idioms', null, null, null),
  ('verbal', 'Idioms', 1, 'What does the idiom "spill the beans" mean?', array['Waste food', 'Tell a lie', 'Reveal a secret', 'Make a mess'], 2, 'To spill the beans is to let a secret out.', 25, 'curated_idioms', null, null, null),
  ('verbal', 'Idioms', 1, 'What does the idiom "burn the midnight oil" mean?', array['Work late into the night', 'Start a fire', 'Waste money', 'Sleep early'], 0, 'It means staying up late to work or study.', 25, 'curated_idioms', null, null, null),
  ('verbal', 'Idioms', 1, 'What does the idiom "a piece of cake" mean?', array['A tough task', 'Something very easy', 'A sweet treat', 'A small reward'], 1, 'A piece of cake is a task that is very easy.', 25, 'curated_idioms', null, null, null),
  ('verbal', 'Idioms', 1, 'What does the idiom "cost an arm and a leg" mean?', array['Be dangerous', 'Be very painful', 'Be very expensive', 'Be cheap'], 2, 'Something that costs an arm and a leg is very expensive.', 25, 'curated_idioms', null, null, null),
  ('verbal', 'Idioms', 1, 'What does the idiom "under the weather" mean?', array['Being very busy', 'Being outdoors', 'Feeling ill', 'Feeling happy'], 2, 'Under the weather means slightly unwell.', 25, 'curated_idioms', null, null, null),
  ('verbal', 'Idioms', 2, 'What does the idiom "bite the bullet" mean?', array['Avoid a problem', 'Eat quickly', 'Get hurt', 'Face something difficult bravely'], 3, 'To bite the bullet is to accept something unpleasant and get on with it.', 25, 'curated_idioms', null, null, null),
  ('verbal', 'Idioms', 1, 'What does the idiom "call it a day" mean?', array['Stop working for now', 'Celebrate', 'Start early', 'Name a day'], 0, 'To call it a day is to stop what you are doing for the day.', 25, 'curated_idioms', null, null, null),
  ('reasoning', 'Puzzles', 2, 'There are 25 horses and a track that races 5 at a time. There is no stopwatch, so a race only tells you the finishing order. What is the fewest races needed to find the single fastest horse?', array['5', '25', '7', '6'], 3, 'Race 5 groups of 5, then race the 5 group winners. The winner of that 6th race is the fastest.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 3, 'There are 25 horses and a track that races 5 at a time. There is no stopwatch, so a race only tells you the finishing order. What is the fewest races needed to find the 3 fastest horses?', array['7', '11', '8', '6'], 0, 'Race 5 groups of 5 (5 races), then race the group winners (race 6); its winner is the fastest. Only 5 horses can still be 2nd or 3rd: the 2nd and 3rd of race 6, the 2nd and 3rd from the fastest horse''s group, and the 2nd from the runner-up''s group. Race them (race 7).', 75, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 3, '100 doors are all closed. On pass 1 you toggle every door, on pass 2 every 2nd door, on pass 3 every 3rd door, and so on up to pass 100. How many doors are open at the end?', array['10', '1', '50', '25'], 0, 'A door is toggled once for each of its factors. Only perfect squares have an odd number of factors, so doors 1, 4, 9, …, 100 end up open: 10 doors.', 75, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 3, '100 doors start closed. On pass k (k = 1 to 100) you toggle every k-th door. Which of these doors is open at the end?', array['Door 99', 'Door 50', 'Door 48', 'Door 64'], 3, '64 is a perfect square (8 × 8), so it has an odd number of factors and is toggled an odd number of times. 50, 48 and 99 are not squares, so they end closed.', 75, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 3, 'You have 2 identical eggs and a 100-floor building. An egg breaks if dropped from a certain floor or higher. In the worst case, what is the fewest drops needed to find that floor?', array['14', '7', '10', '50'], 0, 'With d drops, drop the first egg from floor d, then d + (d − 1), and so on, checking the gaps with the second egg. That covers d(d + 1)/2 floors, and the smallest d with d(d + 1)/2 ≥ 100 is 14.', 75, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 3, 'Two ropes each take exactly 60 minutes to burn, but they burn unevenly, and you can only light their ends. Which of these times can you measure exactly?', array['40 minutes', '20 minutes', '45 minutes', '50 minutes'], 2, 'Light rope A at both ends and rope B at one end. A burns out at 30 minutes; then light B''s other end. Its remaining half burns from both ends in 15 minutes, giving 45 in total.', 75, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'Three switches outside a closed room control three bulbs inside. You can flip the switches as you like but enter the room only once. How do you match every switch to its bulb?', array['Leave one switch on for a few minutes, switch it off, switch on another, then go in and touch the bulbs', 'Switch all three on, then go in', 'It cannot be done in one visit', 'Switch one on, then go in and look'], 0, 'The lit bulb belongs to the switch that is on. The warm, dark bulb belongs to the switch you turned off. The cold, dark bulb belongs to the switch you never touched.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'You have 8 identical-looking balls. One is slightly heavier. Using a balance scale, what is the fewest weighings that always finds the heavy ball?', array['2', '3', '4', '1'], 0, 'Weigh 3 against 3. If they balance, weigh the last 2 against each other. If not, take the heavier 3 and weigh 1 against 1: the heavier side wins, or the ball left out if they balance.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'There are 27 coins and one is a lighter fake. With a balance scale, what is the fewest weighings that always finds the fake?', array['9', '5', '3', '4'], 2, 'Each weighing splits the suspects into three equal groups and shows which group holds the fake: 27 → 9 → 3 → 1, so 3 weighings.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 3, 'One of 1,000 bottles is poisoned, and the poison takes exactly 24 hours to act. You have only 24 hours. What is the fewest testers needed to find the poisoned bottle?', array['500', '1,000', '10', '100'], 2, 'Number the bottles in binary. Tester k sips from every bottle whose k-th bit is 1. Who falls ill spells out the poisoned bottle''s number, and 10 bits cover up to 1,024 bottles.', 75, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 3, 'Four people must cross a bridge at night with one torch, which must be carried on every crossing. At most two cross at a time, at the slower person''s pace. They take 1, 2, 5 and 10 minutes. What is the shortest total time?', array['19 minutes', '17 minutes', '21 minutes', '18 minutes'], 1, '1 and 2 cross (2), 1 returns (1), 5 and 10 cross (10), 2 returns (2), 1 and 2 cross (2): 2 + 1 + 10 + 2 + 2 = 17.', 75, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 1, 'At a party, each of 10 people shakes hands with every other person exactly once. How many handshakes are there?', array['100', '50', '45', '90'], 2, 'Each handshake is one pair of people: 10 × 9 / 2 = 45.', 40, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 3, 'A prize is behind one of 3 doors. You pick a door, and the host, who knows where the prize is, opens another door with no prize behind it. If you switch to the remaining door, what is your chance of winning?', array['2/3', '1', '1/3', '1/2'], 0, 'Your first pick is right only 1/3 of the time. In the other 2/3 of cases the host has to leave the prize behind the remaining door, so switching wins 2/3 of the time.', 75, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'Three ants sit at the corners of a triangle. Each picks one of its two edges at random and walks along it at the same speed. What is the chance that no two ants meet?', array['1/2', '3/4', '1/8', '1/4'], 3, 'There are 2 × 2 × 2 = 8 equally likely choices. The ants avoid each other only if all go clockwise or all go anticlockwise: 2 out of 8, so 1/4.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'A snail is at the bottom of a 30 m well. Each day it climbs 3 m, and each night it slips back 2 m. On which day does it reach the top?', array['Day 28', 'Day 30', 'Day 27', 'Day 29'], 0, 'After 27 days and nights it is at 27 m. On day 28 it climbs 3 m, reaches 30 m and is out before it can slip back.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 1, 'A drawer holds 10 black and 10 white socks. In the dark, what is the fewest socks you must take out to be sure of a matching pair?', array['4', '2', '11', '3'], 3, 'With only two colours, any 3 socks must include two of the same colour.', 40, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'A drawer holds 10 black and 10 white socks. In the dark, what is the fewest socks you must take out to be sure of getting 2 black socks?', array['20', '12', '11', '3'], 1, 'In the worst case you first take all 10 white socks. The next 2 must be black: 10 + 2 = 12.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 1, 'A bat and a ball cost ₹110 together. The bat costs ₹100 more than the ball. How much does the ball cost?', array['₹15', '₹55', '₹5', '₹10'], 2, 'If the ball costs x, the bat costs x + 100, so 2x + 100 = 110 and x = 5.', 40, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'A patch of lily pads doubles in size every day. It covers the whole lake on day 48. On which day did it cover half the lake?', array['Day 24', 'Day 47', 'Day 46', 'Day 36'], 1, 'It doubles each day, so one day before covering the whole lake it covered half: day 47.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'If 5 machines make 5 widgets in 5 minutes, how long do 100 machines take to make 100 widgets?', array['1 minute', '5 minutes', '100 minutes', '20 minutes'], 1, 'Each machine makes 1 widget in 5 minutes. 100 machines working at once make 100 widgets in the same 5 minutes.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 3, 'How many squares of any size are there on a standard 8 × 8 chessboard?', array['204', '196', '256', '64'], 0, 'Count each size: 8² + 7² + … + 1² = 64 + 49 + 36 + 25 + 16 + 9 + 4 + 1 = 204.', 75, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'What is the fewest straight cuts needed to cut a round cake into 8 equal pieces?', array['7', '3', '8', '4'], 1, 'Two cuts across the top make 4 equal pieces, and one horizontal cut through the middle doubles that to 8.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'You must pay a worker 1/7 of a gold bar at the end of each day for 7 days. What is the fewest cuts you need to make in the bar?', array['1', '2', '6', '3'], 1, 'Cut it into pieces of 1/7, 2/7 and 4/7. Any amount from 1/7 to 7/7 can be paid by handing over pieces and taking change back.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'There are 10 bags of coins. Real coins weigh 10 g, but every coin in one bag is fake and weighs 9 g. With a digital scale, what is the fewest weighings needed to find the fake bag?', array['10', '2', '1', '3'], 2, 'Take 1 coin from bag 1, 2 from bag 2, and so on up to 10 from bag 10, and weigh them once. The total falls short of 550 g by the number of the fake bag.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 1, '100 players enter a knockout tournament, and every match knocks out its loser. How many matches are needed to find the champion?', array['64', '99', '100', '50'], 1, 'Every player except the champion loses exactly once, and each match has one loser: 99 matches.', 40, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'Three boxes are labelled Apples, Oranges and Mixed, and every label is wrong. Without looking inside, what is the fewest fruits you must take out to label all the boxes correctly?', array['3', '6', '2', '1'], 3, 'The box labelled Mixed holds only one kind, so one fruit from it tells you which. Say it is an apple: that box is Apples. The box labelled Oranges can''t be Oranges, so it is Mixed, and the last box is Oranges.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 1, 'What is the fewest people needed in a room to be sure that at least two were born in the same month?', array['12', '7', '24', '13'], 3, 'There are 12 months, so with 13 people at least two must share a month (the pigeonhole principle).', 40, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'How many times do the hour and minute hands of a clock overlap in 12 hours?', array['11', '24', '22', '12'], 0, 'The minute hand catches the hour hand once every 12/11 hours, so they overlap 11 times in 12 hours.', 55, 'curated_puzzles', null, null, null),
  ('reasoning', 'Puzzles', 2, 'Two trains start 100 km apart and head towards each other at 50 km/h each. A bird flies back and forth between them at 75 km/h until they meet. How far does the bird fly?', array['50 km', '100 km', '150 km', '75 km'], 3, 'The gap closes at 100 km/h, so the trains meet after 1 hour. The bird flies for that hour at 75 km/h: 75 km.', 55, 'curated_puzzles', null, null, null)
